# ! [doc = " Advanced Vector Extensions (AVX)"] # ! [doc = ""] # ! [doc = " The references are:"] # ! [doc = ""] # ! [doc = " - [Intel 64 and IA-32 Architectures Software Developer's Manual Volume 2:"] # ! [doc = "   Instruction Set Reference, A-Z][intel64_ref]. - [AMD64 Architecture"] # ! [doc = "   Programmer's Manual, Volume 3: General-Purpose and System"] # ! [doc = "   Instructions][amd64_ref]."] # ! [doc = ""] # ! [doc = " [Wikipedia][wiki] provides a quick overview of the instructions available."] # ! [doc = ""] # ! [doc = " [intel64_ref]: http://www.intel.de/content/dam/www/public/us/en/documents/manuals/64-ia-32-architectures-software-developer-instruction-set-reference-manual-325383.pdf"] # ! [doc = " [amd64_ref]: http://support.amd.com/TechDocs/24594.pdf"] # ! [doc = " [wiki]: https://en.wikipedia.org/wiki/Advanced_Vector_Extensions"] use split_decls_genesis :: ourprelude :: * ; use crate :: { core_arch :: x86 :: * , mem :: transmute } ; #[doc = " Copies `a` to result, and insert the 64-bit integer `i` into result"] #[doc = " at the location specified by `index`."] #[doc = ""] #[doc = " [Intel's documentation](https://www.intel.com/content/www/us/en/docs/intrinsics-guide/index.html#text=_mm256_insert_epi64)"] #[inline] #[rustc_legacy_const_generics (2)] #[target_feature (enable = "avx")] #[stable (feature = "simd_x86" , since = "1.27.0")] pub fn _mm256_insert_epi64 < const INDEX : i32 > (a : __m256i , i : i64) -> __m256i { static_assert_uimm_bits ! (INDEX , 2) ; unsafe { transmute (simd_insert ! (a . as_i64x4 () , INDEX as u32 , i)) } } #[doc = " Extracts a 64-bit integer from `a`, selected with `INDEX`."] #[doc = ""] #[doc = " [Intel's documentation](https://www.intel.com/content/www/us/en/docs/intrinsics-guide/index.html#text=_mm256_extract_epi64)"] #[inline] #[target_feature (enable = "avx")] #[rustc_legacy_const_generics (1)] #[stable (feature = "simd_x86" , since = "1.27.0")] pub fn _mm256_extract_epi64 < const INDEX : i32 > (a : __m256i) -> i64 { static_assert_uimm_bits ! (INDEX , 2) ; unsafe { simd_extract ! (a . as_i64x4 () , INDEX as u32) } } #[cfg (test)] mod tests { use stdarch_test :: simd_test ; use crate :: core_arch :: arch :: x86_64 :: * ; #[simd_test (enable = "avx")] unsafe fn test_mm256_insert_epi64 () { let a = _mm256_setr_epi64x (1 , 2 , 3 , 4) ; let r = _mm256_insert_epi64 :: < 3 > (a , 0) ; let e = _mm256_setr_epi64x (1 , 2 , 3 , 0) ; assert_eq_m256i (r , e) ; } #[simd_test (enable = "avx")] unsafe fn test_mm256_extract_epi64 () { let a = _mm256_setr_epi64x (0 , 1 , 2 , 3) ; let r = _mm256_extract_epi64 :: < 3 > (a) ; assert_eq ! (r , 3) ; } }